#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# The owner's step for M6's custom-domain staging run (.github/workflows/m6-custom-domain-staging.yml,
# docs/staging.md "M6's staging run for custom domains"): a Cloudflare API token that can edit DNS on opster.dev and
# nothing else, and opster.dev's zone ID, set as secrets of the GitHub environment staging-dns, beside a copy of the
# test sign-up secret. Run it yourself, at a terminal:
#
#   scripts/wizards/opster-dns-token.sh
#
# Nothing typed is echoed, written to a file or passed on a command line: each value goes to `gh secret set` and to
# curl on standard input. The checks it makes are reads: the token's own verification, and a listing of one record.

OPSTER_REPO="thachp/podster"
OPSTER_ENV="staging-dns"
OPSTER_DOMAIN="opster.dev"
SIGNUP_FILE="$HOME/.podster/e2e-signup-secret.staging"

# set_env_secret NAME VALUE sets a secret of the staging-dns environment, the value on gh's standard input.
set_env_secret() {
  local name="$1" value="$2"
  if printf '%s' "$value" | gh secret set "$name" --env "$OPSTER_ENV" --repo "$OPSTER_REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s in the %s environment\n' "$GREEN" "$RESET" "$name" "$OPSTER_ENV"
    return 0
  fi
  SKIPPED+=("$name in $OPSTER_ENV (gh secret set $name --env $OPSTER_ENV --repo $OPSTER_REPO, value at the prompt)")
  warn "couldn't set $name; set it later: gh secret set $name --env $OPSTER_ENV --repo $OPSTER_REPO"
  return 1
}

# cf_get URL_PATH TOKEN prints Cloudflare's answer to a GET. The token and the URL go to curl as a config on standard
# input (-K -), so neither is on a command line.
cf_get() {
  printf 'header = "Authorization: Bearer %s"\nurl = "https://api.cloudflare.com/client/v4/%s"\nsilent\nmax-time = 20\n' "$2" "$1" | curl -K - 2>/dev/null || true
}

# ninety_days_out prints the date 90 days from today, on macOS or Linux.
ninety_days_out() {
  date -v+90d +%Y-%m-%d 2>/dev/null || date -d '+90 days' +%Y-%m-%d 2>/dev/null || printf 'about 90 days from today'
}

usage() {
  cat <<EOF
Usage: scripts/wizards/opster-dns-token.sh [--help]

Walks the owner through making a Cloudflare API token with Zone, DNS, Edit on $OPSTER_DOMAIN alone (no Zone Read, an
expiry about 90 days out, no IP filtering), and sets it, $OPSTER_DOMAIN's zone ID and a copy of the test sign-up secret
as secrets of the GitHub environment $OPSTER_ENV in $OPSTER_REPO:
OPSTER_DNS_TOKEN, OPSTER_ZONE_ID and PODSTER_E2E_SIGNUP_SECRET.

It needs gh, signed in with admin rights on the repository, and curl. The environment must already exist (the
architect makes it, deployable from main only). Nothing typed is echoed or written to a file. It changes nothing on
Cloudflare: you make the token in the dashboard; it only reads, to check the token and the zone ID.
EOF
}

run_wizard() {

if [[ "${1:-}" == "--help" || "${1:-}" == "-h" ]]; then
  usage
  return 0
fi
if (( $# )); then
  usage >&2
  return 2
fi

# Nothing is kept in a .env file: the values go to GitHub alone.
ENV_FILE=/dev/null
TOTAL_STAGES=5
EXPIRES="$(ninety_days_out)"

banner "opster.dev DNS token for the custom-domain staging run"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "GitHub: check gh and the $OPSTER_ENV environment"
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh isn't installed or isn't signed in. Run gh auth login, then this wizard again."
  return 1
fi
if ! command -v curl >/dev/null 2>&1; then
  warn "curl isn't installed: the wizard uses it to check the token."
  return 1
fi
if ! gh api "repos/$OPSTER_REPO/environments/$OPSTER_ENV" --jq .name >/dev/null 2>&1; then
  warn "The environment $OPSTER_ENV doesn't exist in $OPSTER_REPO yet. The architect makes it, deployable from main"
  warn "only; ask for it, then run this wizard again. Nothing was set."
  return 1
fi
say "The environment $OPSTER_ENV exists. Its deployment branches:"
note "  $(gh api "repos/$OPSTER_REPO/environments/$OPSTER_ENV" --jq 'if .deployment_branch_policy == null then "any branch (ask the architect to limit it to main)" else "limited by a policy" end' 2>/dev/null || printf 'unread')"
pause "Press Enter to continue"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: make the token"
say "Sign in to Cloudflare as a member of the account that holds podster.dev and $OPSTER_DOMAIN."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "My Profile → API Tokens → Create Token → Custom token → Get started."
step "Token name: podster staging DNS opster.dev"
step "Permissions: one row only, Zone · DNS · Edit. Don't add Zone · Zone · Read, or anything else."
step "Zone Resources: Include · Specific zone · $OPSTER_DOMAIN."
step "Client IP Address Filtering: leave it empty (GitHub's runners have no fixed address)."
step "TTL: start today, end $EXPIRES."
step "Continue to summary. Check it lists exactly: $OPSTER_DOMAIN - DNS:Edit. Then Create Token."
note "Cloudflare shows the token once. Leave the page open until the next stage has it."
pause "Press Enter once the token is shown"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "GitHub: store the token as OPSTER_DNS_TOKEN"
OPSTER_DNS_TOKEN=""
while :; do
  ask_secret OPSTER_DNS_TOKEN "Paste the token (hidden):" || { warn "no token read"; return 1; }
  if [[ ! "$OPSTER_DNS_TOKEN" =~ ^[A-Za-z0-9_-]{40,}$ ]]; then
    warn "That isn't shaped like a Cloudflare API token. Copy it again."
    continue
  fi
  if cf_get "user/tokens/verify" "$OPSTER_DNS_TOKEN" | grep -q '"status":"active"'; then
    say "Cloudflare reads the token active."
    break
  fi
  warn "Cloudflare didn't read that token as active. Check you copied all of it."
  confirm "Try again?" || { OPSTER_DNS_TOKEN=""; return 1; }
done
set_env_secret OPSTER_DNS_TOKEN "$OPSTER_DNS_TOKEN" || true
pause "Press Enter to continue"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: $OPSTER_DOMAIN's zone ID, as OPSTER_ZONE_ID"
open_url "https://dash.cloudflare.com/"
step "Open the account that holds $OPSTER_DOMAIN, then the zone $OPSTER_DOMAIN."
step "Overview: in the right-hand column, under API, find Zone ID and click to copy it."
note "It must be $OPSTER_DOMAIN's, not podster.dev's or podster.site's."
OPSTER_ZONE_ID=""
while :; do
  ask_secret OPSTER_ZONE_ID "Paste the zone ID (hidden):" || { warn "no zone ID read"; OPSTER_DNS_TOKEN=""; return 1; }
  if [[ ! "$OPSTER_ZONE_ID" =~ ^[0-9a-f]{32}$ ]]; then
    warn "A zone ID is 32 characters of 0-9 and a-f. Copy it again."
    continue
  fi
  if cf_get "zones/$OPSTER_ZONE_ID/dns_records?per_page=1" "$OPSTER_DNS_TOKEN" | grep -q '"success":true'; then
    say "The token can list records in that zone."
    break
  fi
  warn "The token couldn't list records in that zone: the zone ID is another zone's, or the token isn't DNS Edit on $OPSTER_DOMAIN."
  confirm "Try again?" || { OPSTER_DNS_TOKEN=""; OPSTER_ZONE_ID=""; return 1; }
done
set_env_secret OPSTER_ZONE_ID "$OPSTER_ZONE_ID" || true
OPSTER_DNS_TOKEN=""
OPSTER_ZONE_ID=""
note "You can close the token's page in Cloudflare now."
pause "Press Enter to continue"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "GitHub: the test sign-up secret in $OPSTER_ENV"
say "A job can use one environment, so the run's environment holds its own copy of PODSTER_E2E_SIGNUP_SECRET,"
say "the same value staging-e2e holds."
if [[ -f "$SIGNUP_FILE" ]] && confirm "Copy it from $SIGNUP_FILE?"; then
  # Read as $(cat ...) is, without its last newline, as docs/staging.md passes it to the local runs.
  SIGNUP_SECRET="$(cat "$SIGNUP_FILE")"
  set_env_secret PODSTER_E2E_SIGNUP_SECRET "$SIGNUP_SECRET" || true
  SIGNUP_SECRET=""
else
  SIGNUP_SECRET=""
  if ask_secret SIGNUP_SECRET "Paste the test sign-up secret (hidden), or press Enter to skip:" && [[ -n "$SIGNUP_SECRET" ]]; then
    set_env_secret PODSTER_E2E_SIGNUP_SECRET "$SIGNUP_SECRET" || true
  else
    SKIPPED+=("PODSTER_E2E_SIGNUP_SECRET in $OPSTER_ENV")
  fi
  SIGNUP_SECRET=""
fi
say "The environment's secrets, by name:"
for name in OPSTER_DNS_TOKEN OPSTER_ZONE_ID PODSTER_E2E_SIGNUP_SECRET; do
  if gh secret list --env "$OPSTER_ENV" --repo "$OPSTER_REPO" --json name --jq '.[].name' 2>/dev/null | grep -qx "$name"; then
    note "  ✓ $name"
  else
    note "  ✗ $name is missing"
  fi
done
say "Renew the token before $EXPIRES by running this wizard again."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
